   406	    /// Sets the proxy-stored runtime `version` for this logic
   407	    /// (initializer-like).
   408	    ///
   409	    /// Intended to be called via a proxy ([`delegate_call`][delegate_call]) to
   410	    /// record `VERSION_NUMBER` in the proxy’s storage.
   411	    ///
   412	    /// # Arguments
   413	    ///
   414	    /// * `&mut self` - Write access to the contract's state.
   415	    ///
   416	    /// # Errors
   417	    ///
   418	    /// * [`Error::UnauthorizedCallContext`] - If not called via proxy
   419	    ///   `[`delegate_call`][delegate_call]`.
   420	    /// * [`Error::InvalidVersion`] - If the proxy's stored `version` is greater
   421	    ///   than this logic's `VERSION_NUMBER`.
   422	    ///
   423	    /// [delegate_call]: stylus_sdk::call::delegate_call
   424	    pub fn set_version(&mut self) -> Result<(), Error> {
   425	        if self.not_delegated().is_ok() {
   426	            return Err(Error::UnauthorizedCallContext(
   427	                UUPSUnauthorizedCallContext {},
   428	            ));
   429	        }
   430	        if self.version.get() > VERSION_NUMBER {
   431	            return Err(Error::InvalidVersion(InvalidVersion {
   432	                current_version: self.version.get().to(),
   433	            }));
   434	        }
   435	
   436	        self.version.set(VERSION_NUMBER);
   437	        Ok(())
   438	    }
   439	}
