  1020	    ///   [`IErc721Receiver::on_erc721_received`] reverted with revert data.
  1021	    pub fn _check_on_erc721_received(
  1022	        &mut self,
  1023	        operator: Address,
  1024	        from: Address,
  1025	        to: Address,
  1026	        token_id: U256,
  1027	        data: &Bytes,
  1028	    ) -> Result<(), Error> {
  1029	        if self.vm().code_size(to) == 0 {
  1030	            return Ok(());
  1031	        }
  1032	
  1033	        let receiver = IErc721ReceiverInterface::new(to);
  1034	        let call = Call::new_mutating(self);
  1035	        let result = receiver.on_erc_721_received(
  1036	            self.vm(),
  1037	            call,
  1038	            operator,
  1039	            from,
  1040	            token_id,
  1041	            data.to_vec().into(),
  1042	        );
  1043	
  1044	        let id = match result {
  1045	            Ok(id) => id,
  1046	            Err(e) => {
  1047	                if let stylus_sdk::stylus_core::calls::errors::Error::Revert(
  1048	                    ref reason,
  1049	                ) = e
  1050	                {
  1051	                    if !reason.is_empty() {
  1052	                        return Err(Error::InvalidReceiverWithReason(
  1053	                            InvalidReceiverWithReason {
  1054	                                reason: String::from_utf8_lossy(reason)
  1055	                                    .to_string(),
  1056	                            },
  1057	                        ));
  1058	                    }
  1059	                }
  1060	
  1061	                // Non-IERC721Receiver implementer.
  1062	                return Err(ERC721InvalidReceiver { receiver: to }.into());
  1063	            }
  1064	        };
  1065	
  1066	        // Token rejected.
  1067	        if id != RECEIVER_FN_SELECTOR {
  1068	            return Err(ERC721InvalidReceiver { receiver: to }.into());
  1069	        }
  1070	
  1071	        Ok(())
  1072	    }
  1073	}
