1030	    pub fn _deposit(
1031	        &mut self,
1032	        caller: Address,
1033	        receiver: Address,
1034	        assets: U256,
1035	        shares: U256,
1036	        erc20: &mut Erc20,
1037	    ) -> Result<(), Error> {
1038	        // If asset() is ERC-777, `transfer_from` can trigger a reentrancy
1039	        // BEFORE the transfer happens through the `tokens_to_send` hook. On the
1040	        // other hand, the `token_received` hook, that is triggered after the
1041	        // transfer, calls the vault, which is assumed not malicious.
1042	        //
1043	        // Conclusion: we need to do the transfer before we mint so that any
1044	        // reentrancy would happen before the assets are transferred and before
1045	        // the shares are minted, which is a valid state.
1046	
1047	        self.safe_erc20.safe_transfer_from(
1048	            self.asset(),
1049	            caller,
1050	            self.vm().contract_address(),
1051	            assets,
1052	        )?;
1053	
1054	        erc20._mint(receiver, shares)?;
1055	
1056	        self.vm().log(Deposit {
1057	            sender: caller,
1058	            owner: receiver,
1059	            assets,
1060	            shares,
1061	        });
1062	
1063	        Ok(())
1064	    }
