1066	    /// Withdraw/redeem common workflow.
1067	    ///
1068	    /// # Arguments
1069	    ///
1070	    /// * `caller` - Address initiating the withdrawal.
1071	    /// * `receiver` - Address receiving the assets.
1072	    /// * `owner` - Address owning the shares.
1073	    /// * `assets` - Amount of underlying tokens to transfer.
1074	    /// * `shares` - Amount of shares to burn.
1075	    /// * `erc20` - Write access to an [`Erc20`] contract.
1076	    ///
1077	    /// # Errors
1078	    ///
1079	    /// * [`erc20::Error::InsufficientAllowance`] - If `caller` needs allowance.
1080	    /// * [`erc20::Error::InvalidApprover`] - If `owner` is [`Address::ZERO`].
1081	    /// * [`erc20::Error::InsufficientBalance`] - If `owner` lacks shares.
1082	    /// * [`safe_erc20::Error::SafeErc20FailedOperation`] - If transfer fails.
1083	    ///
1084	    /// # Events
1085	    ///
1086	    /// * [`Withdraw`]
1087	    pub fn _withdraw(
1088	        &mut self,
1089	        caller: Address,
1090	        receiver: Address,
1091	        owner: Address,
1092	        assets: U256,
1093	        shares: U256,
1094	        erc20: &mut Erc20,
1095	    ) -> Result<(), Error> {
1096	        if caller != owner {
1097	            erc20._spend_allowance(owner, caller, shares)?;
1098	        }
1099	
