 562	    pub fn _spend_allowance(
 563	        &mut self,
 564	        owner: Address,
 565	        spender: Address,
 566	        value: U256,
 567	    ) -> Result<(), Error> {
 568	        if let Some(allowance) =
 569	            self._allowance_after_spend(owner, spender, value)?
 570	        {
 571	            self.allowances.setter(owner).insert(spender, allowance);
 572	        }
