 577	    /// Returns the finite allowance remaining after a spend, validating the
 578	    /// same conditions as `_spend_allowance` without changing storage.
 579	    fn _allowance_after_spend(
 580	        &self,
 581	        owner: Address,
 582	        spender: Address,
 583	        value: U256,
 584	    ) -> Result<Option<U256>, Error> {
 585	        let current_allowance = self.allowance(owner, spender);
 586	        if current_allowance == U256::MAX {
 587	            return Ok(None);
 588	        }
 589	        if current_allowance < value {
 590	            return Err(Error::InsufficientAllowance(
 591	                ERC20InsufficientAllowance {
 592	                    spender,
 593	                    allowance: current_allowance,
 594	                    needed: value,
 595	                },
 596	            ));
 597	        }
 598	        if owner.is_zero() {
 599	            return Err(Error::InvalidApprover(ERC20InvalidApprover {
 600	                approver: Address::ZERO,
 601	            }));
 602	        }
 603	        if spender.is_zero() {
 604	            return Err(Error::InvalidSpender(ERC20InvalidSpender {
 605	                spender: Address::ZERO,
 606	            }));
 607	        }
 608	
 609	        Ok(Some(current_allowance - value))
 610	    }
 611	}
