 225	        for token_id in token_ids {
 226	            // This is an "unsafe" transfer that doesn't call any hook on
 227	            // the receiver. With [`IErc721Wrapper::underlying()`] being trusted
 228	            // (by design of this contract) and no other contracts expected to
 229	            // be called from there, we are safe.
 230	            let call = Call::new_mutating(self);
 231	            match underlying.transfer_from(
 232	                self.vm(),
 233	                call,
 234	                sender,
 235	                contract_address,
 236	                token_id,
 237	            ) {
 238	                Ok(()) => (),
 239	                Err(e) => {
 240	                    if let stylus_sdk::stylus_core::calls::errors::Error::Revert(ref reason) = e {
 241	                        if !reason.is_empty() {
 242	                            return Err(Error::InvalidReceiverWithReason(
 243	                                erc721::InvalidReceiverWithReason {
 244	                                    reason: String::from_utf8_lossy(reason)
 245	                                        .to_string(),
 246	                                },
 247	                            ));
 248	                        }
 249	                    }
 250	                    return Err(Error::Erc721FailedOperation(
 251	                        Erc721FailedOperation { token: self.underlying() },
 252	                    ));
 253	                }
